/* @autogenerated */
package net.civeira.phylax.bootstrap.install;

import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.migration.MigrationSeed;
import net.civeira.phylax.common.infrastructure.store.BinaryContent;
import net.civeira.phylax.feature.template.template.domain.Template;
import net.civeira.phylax.feature.template.template.domain.TemplateChangeSet;
import net.civeira.phylax.feature.template.template.domain.TemplateChannelOptions;
import net.civeira.phylax.feature.template.template.domain.gateway.TemplateCommandRepositoryGateway;
import net.civeira.phylax.feature.template.template.domain.gateway.TemplateFilter;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersion;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersionChangeSet;
import net.civeira.phylax.feature.template.templateversion.domain.gateway.TemplateVersionCommandRepositoryGateway;
import net.civeira.phylax.feature.template.theme.domain.Theme;
import net.civeira.phylax.feature.template.theme.domain.gateway.ThemeCommandRepositoryGateway;
import net.civeira.phylax.feature.template.theme.domain.gateway.ThemeFilter;
import net.civeira.phylax.feature.template.themeasset.domain.ThemeAsset;
import net.civeira.phylax.feature.template.themeasset.domain.ThemeAssetChangeSet;
import net.civeira.phylax.feature.template.themeasset.domain.gateway.ThemeAssetCommandRepositoryGateway;
import net.civeira.phylax.feature.template.themeasset.domain.gateway.ThemeAssetContentUploadGateway;
import net.civeira.phylax.feature.template.themeasset.domain.gateway.ThemeAssetFilter;

/**
 * Seeds the page templates of the observability viewer ({@code observe.app}, rendered into the
 * {@code corporate-full} layout) and the {@code brand.css} of the corporate themes, the variables
 * the viewer takes its colors from. Idempotent: each item is created only if it does not exist, so
 * it also completes an installation made before the trait.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class InstallObserveDocuments implements MigrationSeed {

  private static final String BRAND = "brand.css";
  private static final String BRAND_PATH = "migration/seed/assets/observe/brand.css";
  /** Page template: the brand variables of the theme and the viewer fragment. */
  private static final String PAGE =
      "<link rel=\"stylesheet\" href=\"{{theme_assets_path}}/brand.css\">{{{innerContent}}}";

  private final TemplateCommandRepositoryGateway templates;
  private final TemplateVersionCommandRepositoryGateway templateVersions;
  private final ThemeCommandRepositoryGateway themes;
  private final ThemeAssetCommandRepositoryGateway themeAssets;
  private final ThemeAssetContentUploadGateway themeAssetContent;

  @Override
  public String id() {
    return "seed/install-observe-documents";
  }

  @Override
  public int order() {
    // After InitialDocument (30), which creates the corporate themes
    return 35;
  }

  @Override
  @Transactional
  public void run() {
    createTemplate("observe.app", "corporate-full");
    for (String themeName : new String[] {"corporate", "corporate-full"}) {
      themes.find(ThemeFilter.builder().name(themeName).build()).ifPresent(this::installBrand);
    }
  }

  private void createTemplate(final String code, final String themeName) {
    if (templates.find(TemplateFilter.builder().code(code).build()).isPresent()) {
      return;
    }
    TemplateChangeSet template = new TemplateChangeSet().newUid().code(code)
        .channel(TemplateChannelOptions.HTML).theme(themeName).enabled(true);
    Template created = templates.create(Template.create(template));
    TemplateVersionChangeSet version =
        new TemplateVersionChangeSet().newUid().template(created).subject(code).contentHtml(PAGE);
    templateVersions.create(TemplateVersion.create(version));
  }

  private void installBrand(final Theme theme) {
    if (themeAssets.find(ThemeAssetFilter.builder().theme(theme).code(BRAND).build()).isPresent()) {
      return;
    }
    BinaryContent content = load();
    String temporal = themeAssetContent.storeTemporalContent(content);
    ThemeAssetChangeSet change = new ThemeAssetChangeSet().newUid().theme(theme).code(BRAND)
        .type(content.getContentType()).content("temp://" + temporal).enabled(true);
    themeAssets.create(ThemeAsset.create(change));
  }

  private BinaryContent load() {
    try (InputStream stream =
        Thread.currentThread().getContextClassLoader().getResourceAsStream(BRAND_PATH)) {
      if (null == stream) {
        throw new IllegalStateException("Missing install resource: " + BRAND_PATH);
      }
      byte[] data = stream.readAllBytes();
      return BinaryContent.builder().name(BRAND).contentType("text/css")
          .lastModification(Instant.now().toEpochMilli())
          .inputStream(new java.io.ByteArrayInputStream(data)).build();
    } catch (IOException ex) {
      throw new IllegalStateException("Cannot read install resource: " + BRAND_PATH, ex);
    }
  }
}
